// Normaliza los datos, sin importar si vinieron del formulario web
// o del bot de WhatsApp. Los dos mandan (al menos) estos campos:
//   name, service, date, nights, people, message, phone, lang, canal, code
const data = $input.first().json.body || {};

const nights = parseInt(data.nights || '1', 10) || 1;
let startDate = '';
let endDate = '';

if (data.date) {
  const start = new Date(data.date + 'T00:00:00');
  const end = new Date(start);
  end.setDate(end.getDate() + nights);
  const fmt = (d) => d.toISOString().slice(0, 10);
  startDate = fmt(start);
  endDate = fmt(end);
}

const now = new Date();

// El formulario web (submitBooking) todavía no genera código de
// reserva, así que si no viene ninguno le armamos uno acá mismo
// para que TODAS las filas del Sheet tengan uno.
function generarCodigo() {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  let s = '';
  for (let i = 0; i < 5; i++) s += chars[Math.floor(Math.random() * chars.length)];
  return 'ARR-' + s;
}
const codigo = data.code || generarCodigo();

return [{
  json: {
    fechaRegistro: now.toISOString().slice(0, 19).replace('T', ' '),
    codigoReserva: codigo,
    nombre: data.name || '',
    telefono: data.phone || '',
    servicio: data.service || '',
    fechaReserva: data.date || '',
    noches: nights,
    personas: data.people || '',
    mensaje: data.message || '',
    idioma: data.lang || '',
    canal: data.canal || 'formulario_web',
    esHospedagem: (data.service === 'Hospedagem'),
    startDate,
    endDate,
    calSummary: 'Reservado - ' + (data.name || 'Cliente') + ' (' + codigo + ')',
    calDescription: 'Reserva recibida por ' + (data.canal || 'formulario_web') + '.\nCódigo: ' + codigo +
      '\nNombre: ' + (data.name || '') +
      '\nTeléfono: ' + (data.phone || '') +
      '\nPersonas: ' + (data.people || '') +
      '\nServicio: ' + (data.service || '') +
      (data.message ? ('\nMensaje: ' + data.message) : '')
  }
}];
